  n = len(ratings)
  memo = {}

  def rating_sum(i):
    if i >= n:
      return 0
    if i in memo:
      return memo[i]
    memo[i] = max(ratings[i] + rating_sum(i + 2), rating_sum(i + 1))
    return memo[i]

  return rating_sum(0)

